package glitch

import data.glitch_lib

# Credential-related keywords pattern
is_credential_field(name) {
    lower_name := lower(name)
    regex.match("(?:password|passwd|pwd|secret|token|credential|passphrase|api_key|api_secret|access_key|encryption_key|private_key|activationkey|auth_token|client_secret|master_key|signing_key)", lower_name)
}

# Check for empty values: Null, Undef, or empty string
is_empty_value(value) {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
} else {
    value.ir_type == "String"
    count(value.value) == 0
}

# Filter out default/placeholder variables that are intentionally empty
# - Chef: default['...'] are attribute precedence levels (template placeholders)
# - Ansible: variables with __ are role defaults meant to be overridden
is_default_placeholder(name) {
    lower_name := lower(name)
    startswith(lower_name, "default[")
} else {
    lower_name := lower(name)
    contains(lower_name, "__")
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_credential_field(var.name)
    is_empty_value(var.value)
    not is_default_placeholder(var.name)

    result := {
        "type": "sec_empty_pass",
        "element": var,
        "path": parent.path,
        "description": "Empty password in configuration file - Passwords and other credentials should not be empty. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    is_credential_field(attr.name)
    is_empty_value(attr.value)
    not is_default_placeholder(attr.name)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Passwords and other credentials should not be empty. (CWE-258)"
    }
}

